import "server-only";
import { withAuth } from "@workos-inc/authkit-nextjs";
import type { User as WorkOSUser } from "@workos-inc/node";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
  // Set once the user has signed in through WorkOS AuthKit.
  workosId?: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Links a WorkOS identity to a Notely user: matches by WorkOS id, then by email
// (so existing team members keep their record), otherwise creates a new user.
export async function upsertUserFromAuth(authUser: WorkOSUser): Promise<User> {
  const email = authUser.email.toLowerCase();
  const name =
    [authUser.firstName, authUser.lastName].filter(Boolean).join(" ") || email.split("@")[0];

  let user =
    users.find((u) => u.workosId === authUser.id) ??
    users.find((u) => u.email.toLowerCase() === email);

  if (user) {
    user.workosId = authUser.id;
    user.email = email;
  } else {
    user = {
      id: String(users.length + 1),
      email,
      name,
      createdAt: new Date().toISOString().slice(0, 10),
      workosId: authUser.id,
    };
    users.push(user);
  }
  return user;
}

// Returns the signed-in user, or undefined for visitors.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  return user ? upsertUserFromAuth(user) : undefined;
}

// Returns the signed-in user, redirecting to AuthKit sign-in if there isn't one.
export async function requireCurrentUser(): Promise<User> {
  const { user } = await withAuth({ ensureSignedIn: true });
  return upsertUserFromAuth(user);
}
